contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(address(this).balance >= a);
        uint256 balBefore = address(c).balance;
        uint256 accBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: a}(); if (__ESBMC_reverted()) return;

        uint256 balAfter = address(c).balance;
        uint256 accAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(balAfter == balBefore + a && accAfter == accBefore + a);
    }

    receive() external payable {}
}

