// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a);
        uint256 balBefore = address(c).balance;
        uint256 accBefore;
        try c.balances(address(this)) returns (uint256 __r) { accBefore = __r; } catch { return; }
        try c.Deposit{value: a}() {} catch { return; }
        uint256 balAfter = address(c).balance;
        uint256 accAfter;
        try c.balances(address(this)) returns (uint256 __r) { accAfter = __r; } catch { return; }
        assertTrue(balAfter == balBefore + a && accAfter == accBefore + a);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
